from pathlib import Path
import json,shutil
R=Path(__file__).resolve().parent
q=json.loads((R/'qa.json').read_text())
def fig(stem,title):
 return f'<figure><div class="scroll"><img class="pixel scaled" data-stem="{stem}" src="previews/{stem}-native.png" alt="{title}"></div><figcaption>{title}</figcaption></figure>'
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chapter2 Batch7 · Final background polish</title><link rel="stylesheet" href="gallery.css"></head><body><header><div class="eyebrow">The Acceptable Error / Chapter2 / Batch7 / November17,2026</div><h1>Final background polish.</h1><p class="status">A–H approved without changes · I generated, awaiting final selection</p><p>The Customs inspector retains every injector and shadow pixel. Only the speckled gray background is simplified. The original image and all source generations remain preserved.</p><nav><a href="#items">Original and revision</a><a href="#groups">Pixel proof</a><a href="#evidence">QA and provenance</a></nav></header><div class="toolbar"><div class="toolbar-inner"><div class="button-group"><button data-scale="1" aria-pressed="true">Native pixels</button><button data-scale="4" aria-pressed="false">Exact4×</button></div></div></div><main><section id="items"><h2>Asset I only</h2><p>565×451 opaque RGB · existing64-color palette · exact nearest-neighbor4× views · no blur or regeneration.</p>'''
for stem,title,path in [('I-original','Original reviewed I','references/I-customs-antidote-inspect.png'),('I-revised','Revised I — generated and unselected',q['candidatePath'])]:
 html+=f'<article class="asset" data-width="565" data-height="451"><header><h3>{title}</h3></header>'+fig(stem,title)+f'<p><a href="{path}">Native PNG</a> · <a href="previews/{stem}-4x.png">Exact4× PNG</a></p></article>'
html+='</section><section id="groups"><h2>Comparison and preservation proof</h2>'
for stem,title in [('I-original-vs-revised','Original versus revised I, native or exact4×'),('changed-pixels','Changed-pixel mask: white pixels changed, black pixels unchanged'),('changed-overlay','Changed pixels shown in red over the original'),('protected-injector-and-shadow','Protected injector and shadow, including one native pixel of safety margin'),('permitted-background-edit','Permitted background region: white is editable; black remains protected'),('inspector-background-continuity','Approved Public C and Maintenance F beside revised Customs I; C/F unchanged')]:html+=fig(stem,title)
html+='</section><section id="evidence"><h2>Technical result</h2><p>'+str(q['changedPixels'])+' background pixels changed. Zero changes outside the permitted background mask. Zero changes to protected injector or shadow pixels. Silhouette, hardware, reservoir, folded label and composition are preserved. No colors were introduced.</p><p>The cleanup replaces the secondary gray speckles with the existing dominant gray only in the exterior background. The protected foreground and shadow hashes match before and after. Any original surface texture on the device is intentionally preserved.</p><p>Owner-approved A–H require no further review. All108 selected public hashes are verified in the publication receipt. Revised I remains outside selected-art previews.</p><div class="docs">'
for p,t in [('qa.json','Pixel and preservation QA'),('manifest.json','Revised candidate path and SHA-256'),('SHA256SUMS.txt','Review-file checksums'),('README.md','Scope and source provenance'),('PMO_HANDOFF.md','Three approved phrase corrections'),('REMAINING_QUEUE.md','I pending; five death screens not started')]:html+=f'<a class="doc" href="{p}"><strong>{t}</strong><span>{p}</span></a>'
html+='''</div><p>Original generation and processing history: <a href="https://github.com/InterstellarHarvest/CYOA/tree/306aa694295829b6e0a13b25f78ed6b004826ffd/review/chapter-02-batch07-2026-11-17">immutable original Batch7 review</a>. Only this background-polish revision awaits final Art Director selection. No gameplay integration or Batch8 generation.</p></section></main><footer>Review-only generated candidate · excluded from selected-art previews</footer><script>'use strict';function setScale(s){document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===s)));document.querySelectorAll('.scaled').forEach(i=>i.src='previews/'+i.dataset.stem+(s===4?'-4x.png':'-native.png'));}document.querySelectorAll('[data-scale]').forEach(b=>b.addEventListener('click',()=>setScale(Number(b.dataset.scale))));</script></body></html>'''
(R/'index.html').write_text(html)
old=R.parent/'chapter-02-batch07-2026-11-17'
shutil.copy2(old/'gallery.css',R/'gallery.css')
print('Two I views, six comparison/mask/continuity views, native/exact4x controls.')
